import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { AlertService } from '@app/_services';
import { Alert } from '@app/_models';

@Component({
  selector: 'app-alert',
  templateUrl: './alert.component.html',
  styleUrls: ['./alert.component.less'],
  standalone: true,
  imports: [CommonModule]
})
export class AlertComponent implements OnInit {
  alerts: Alert[] = [];

  constructor(private alertService: AlertService) { }

  ngOnInit() {
    this.alertService.alert$.subscribe((alert: Alert) => {
      if (!alert.message) {
        this.alerts = [];
        return;
      }

      this.alerts.push(alert);

      if (alert.autoClose) {
        setTimeout(() => this.removeAlert(alert.id), 5000);
      }
    });
  }

  removeAlert(id?: string) {
    this.alerts = this.alerts.filter(x => x.id !== id);
  }
}
<div class="space-y-3 mt-3 mb-3">
  <div *ngFor="let alert of alerts" [ngClass]="'alert alert-' + alert.type + ' alert-dismissible fade show'" role="alert">
    {{ alert.message }}
    <button (click)="removeAlert(alert.id)" type="button" class="btn-close" aria-label="Close"></button>
  </div>
</div>
